`timescale 1ns/1ps
// File vectors are generated by an independent Python integer oracle.
module tb_requant_lane;
 reg clk=0,rst=1,iv=0;always #5 clk=~clk;
 reg signed [31:0] value;reg signed [15:0] multiplier;reg signed [5:0] shift;
 reg signed [3:0] lo,hi;reg [15:0] tag;
 wire ov;wire [3:0] result;wire [15:0] ot;
 requant_lane #(.TAG_WIDTH(16)) dut(.clk(clk),.rst(rst),.in_valid(iv),.in_value(value),
 .in_multiplier(multiplier),.in_shift(shift),.activation_min(lo),.activation_max(hi),
 .in_tag(tag),.out_valid(ov),.out_data(result),.out_tag(ot));
 reg [3:0] expected[0:32767];integer fd,rc,issued=0,checked=0;string path;
 always @(posedge clk) if(ov)begin
  if(ot!==checked[15:0] || result!==expected[checked])$fatal(1,"requant mismatch %0d got %h expected %h",checked,result,expected[checked]);
  checked=checked+1;
 end
 initial begin
  if(!$value$plusargs("VECTORS=%s",path))$fatal(1,"VECTORS required");fd=$fopen(path,"r");
  repeat(3)@(negedge clk);rst=0;
  while(!$feof(fd))begin
   @(negedge clk);rc=$fscanf(fd,"%h %h %h %h %h %h\n",value,multiplier,shift,lo,hi,expected[issued]);
   if(rc!=6)$fatal(1,"bad vector");tag=issued;iv=1;issued=issued+1;
  end
  @(negedge clk);iv=0;repeat(8)@(negedge clk);
  if(checked!=issued)$fatal(1,"requant lost outputs");
  $display("PASS requant independent vectors=%0d II=1",checked);$finish;
 end
endmodule
